import{_ as a}from"./chunks/源操作数搬运场景示例.Bsa4CPbx.js";import{c as e,Q as o,j as s,m as d}from"./chunks/framework.DOi4mjdC.js";const l="/assets/%E7%9B%AE%E7%9A%84%E6%93%8D%E4%BD%9C%E6%95%B0%E6%90%AC%E8%BF%90%E5%9C%BA%E6%99%AF%E7%A4%BA%E4%BE%8B.DYaOBM57.png",P=JSON.parse('{"title":"SetLoopModePara","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetLoopModePara","slug":"setloopmodepara"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory数据搬运/SetLoopModePara.md","filePath":"api/SIMD-API/基础API/Memory数据搬运/SetLoopModePara.md"}'),p={name:"api/SIMD-API/基础API/Memory数据搬运/SetLoopModePara.md"};function r(n,t,i,c,h,_){return o(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="setloopmodepara" tabindex="-1">SetLoopModePara <a class="header-anchor" href="#setloopmodepara" aria-label="Permalink to &quot;SetLoopModePara&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>DataCopy、DataCopyPad过程中通过该接口使能loop mode并且设置loop mode的参数，需要和<a href="./ResetLoopModePara.html">ResetLoopModePara</a>搭配使用，在数据搬运结束后通过ResetLoopModePara重置loop mode的参数。支持的通路如下：</p><ul><li>GM-&gt;VECIN</li><li>VECOUT-&gt;GM</li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void SetLoopModePara(const LoopModeParams&amp; loopParams, DataCopyMVType type)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>loopParams</td><td>输入</td><td>循环模式参数 LoopModeParams类型，定义如下，具体参数说明请参考表2。 &lt;pre class=&quot;screen&quot; id=&quot;screen1929612197911&quot;&gt;struct LoopModeParams { loop1Size = 0; loop2Size = 0; loop1SrcStride = 0; loop1DstStride = 0; loop2SrcStride = 0; loop2DstStride = 0 ; };&lt;/pre&gt;</td></tr><tr><td>type</td><td>输入</td><td>数据搬运模式。DataCopyMVType为枚举类型，定义如下，具体参数说明请参考表3。 &lt;pre class=&quot;screen&quot; id=&quot;screen1354412162247&quot;&gt;enum class DataCopyMVType : uint8_t { UB_TO_OUT = 0, OUT_TO_UB = 1, };&lt;/pre&gt;</td></tr></tbody></table><p><strong>表 2</strong> LoopModeParams结构体参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>loop1Size</td><td>用于设置内层循环的循环次数，数据类型为uint32_t，取值范围为[0, 2^21)。</td></tr><tr><td>loop2Size</td><td>用于设置外层循环的循环次数，数据类型为uint32_t，取值范围为[0, 2^21)。</td></tr><tr><td>loop1SrcStride</td><td>用于设置内层循环中相邻迭代源操作数的数据块间的间隔，单位为Byte，数据类型为uint64_t。 当数据搬运模式是UB_TO_OUT的时候取值范围为[0, 2^21)，并且loop1SrcStride必须32B对齐。当数据搬运模式是OUT_TO_UB的时候取值范围为[0, 2^40)。</td></tr><tr><td>loop1DstStride</td><td>用于设置内层循环中相邻迭代目的操作数的数据块间的间隔，单位为Byte，数据类型为uint64_t。 当数据搬运模式是UB_TO_OUT的时候取值范围为[0, 2^40)。当数据搬运模式是OUT_TO_UB的时候取值范围为[0, 2^21)，并且loop1DstStride必须32B对齐。</td></tr><tr><td>loop2SrcStride</td><td>用于设置外层循环中相邻迭代源操作数的数据块间的间隔，单位为Byte，数据类型为uint64_t。 当数据搬运模式是UB_TO_OUT的时候取值范围为[0, 2^21)，并且loop2SrcStride必须32B对齐。当数据搬运模式是OUT_TO_UB的时候取值范围为[0, 2^40)。</td></tr><tr><td>loop2DstStride</td><td>用于设置外层循环中相邻迭代目的操作数的数据块间的间隔，单位为Byte，数据类型为uint64_t。 当数据搬运模式是UB_TO_OUT的时候取值范围为[0, 2^40)。当数据搬运模式是OUT_TO_UB的时候取值范围为[0, 2^21)，并且loop2DstStride必须32B对齐。</td></tr></tbody></table><p><strong>表 3</strong> DataCopyMVType结构体参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>UB_TO_OUT</td><td>从UB搬运到GM的通路。</td></tr><tr><td>OUT_TO_UB</td><td>从GM搬运到UB的通路。</td></tr></tbody></table><p>下面的样例呈现了SetLoopModePara的使用方法。</p><ul><li>样例中在数据类型为int8_t的场景下，数据块大小为384，配置DataCopyPad的数据搬运模式为Compact模式，blockLen = 48，blockCount = 2，表明每个连续传输数据块包含48Bytes，且连续传输数据块有两个，srcStride = 0, dstStride = 0，isPad = false，表明源操作数相邻数据块之间没有间隔且不需要填充用户自定义的数据；</li><li>再设置SetLoopModePara中LoopModeParams的参数：loop1Size = 2，loop2Size = 2，loop1SrcStride = 96，loop2SrcStride =192，loop1DstStride = 128，loop2DstStride = 288，DataCopyMVType为OUT_TO_UB，表明内层循环和外层循坏的次数分别为2次，内层循环和外层循环中相邻迭代源操作数的数据块间隔分别为96Bytes和192Bytes，内层循环和外层循环中相邻迭代目的操作数的数据块间隔分别为128Bytes和288Bytes，通路是从GM搬运到UB；</li><li>使用以上配置，调用SetLoopModePara再调用DataCopyPad就可以开启DataCopyPad的loop模式完成数据类型为int8_t的数据块大小为384的数据搬运。详细图解如下：</li></ul><p><strong>图 1</strong> 源操作数搬运场景示例<br><img src="'+a+'" alt="" title="源操作数搬运场景示例"></p><p><strong>图 2</strong> 目的操作数搬运场景示例<br><img src="'+l+`" alt="" title="目的操作数搬运场景示例"></p><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>源操作数和目的操作数的起始地址需要保证32字节对齐。</li><li>目的操作数的数据不能重叠，如果有重叠，硬件层面不会报错或者告警，同时也不能保证重叠数据的正确性；但是不同迭代可以交织，例如内层循环中相邻迭代目的操作数的数据块间的间隔可以小于相邻连续目的操作数的数据块的间隔。</li><li>需要在每次使能loop mode并且设置loop mode的参数后通过ResetLoopModePara进行寄存器的复位，否则会影响到下一次对应通路的搬运的使用，引发异常。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本示例中操作数数据类型为int8_t。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;int8_t&gt; srcLocal = inQueueSrc.AllocTensor&lt;int8_t&gt;();</span></span>
<span class="line"><span>AscendC::DataCopyExtParams copyParams{2, 48 * sizeof(int8_t), 0, 0, 0}; // 结构体DataCopyExtParams最后一个参数是rsv保留位</span></span>
<span class="line"><span>AscendC::DataCopyPadExtParams&lt;half&gt; padParams{false, 0, 0, 0};</span></span>
<span class="line"><span>AscendC::LoopModeParams loopParam2Ub {2, 2, 96, 128, 192, 288};</span></span>
<span class="line"><span>AscendC::SetLoopModePara(loopParam2Ub, DataCopyMVType::OUT_TO_UB);</span></span>
<span class="line"><span>AscendC::DataCopyPad&lt;int8_t, PaddingMode::Compact&gt;(srcLocal, srcGlobal, copyParams, padParams); // 从GM-&gt;VECIN搬运 48 * 2 * 2 * 2 = 384Bytes</span></span>
<span class="line"><span>AscendC::ResetLoopModePara(DataCopyMVType::OUT_TO_UB);</span></span>
<span class="line"><span>AscendC::LoopModeParams loopParam2Gm {2, 2, 128, 96, 288, 192};</span></span>
<span class="line"><span>AscendC::SetLoopModePara(loopParams2Gm, DataCopyMVType::UB_TO_OUT);</span></span>
<span class="line"><span>DataCopyPad&lt;T, PaddingMode::Compact&gt;(dstGlobal, srcLocal, copyParams);</span></span>
<span class="line"><span>AscendC::ResetLoopModePara(DataCopyMVType::UB_TO_OUT);</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据src0Global: [1 2 3 ... 384]</span></span>
<span class="line"><span>输出数据dstGlobal:[1 2 3 ... 384]</span></span></code></pre></div>`,28)])])}const b=e(p,[["render",r]]);export{P as __pageData,b as default};
